1	/** Mutable reference authority for explicit development use. No profile admission. */
2	import { randomBytes, createHash } from "node:crypto";
3	import {
4	  isReadProblem,
5	  parseCanonicalScope,
6	  parseTypeDescriptor,
7	  prepareReadUpdateSingleton,
8	  prepareReadUpdateSequence,
9	  stringifyJsonValue,
10	  type ReadUpdateOperation,
11	  type ReadRequest,
12	  type MaximumEndpointMultiplicityPolicy,
13	} from "@bdp/protocol";
14	import { CONTRACT_ARTIFACT_CEILINGS } from "./installed-contract-artifact.js";
15	import { openRecoveryStore } from "./recovery-store.js";
16	import {
17	  createSequenceLifecycle,
18	  type SequenceLifecycle,
19	  type LifecycleScheduler,
20	} from "./sequence-executor.js";
21	import { createReadSequenceLifecycle } from "./read-sequence-lifecycle.js";
22	import {
23	  assertReadUpdateRuntimeCompatibility,
24	  snapshotReadUpdateRuntimeLimits,
25	} from "./read-update-runtime-limits.js";
26	import type { StablePrincipal } from "./member-executor.js";
27	import {
28	  administrativeData,
29	  captureDevelopmentAggregatePolicy,
30	  assertDevelopmentContracts,
31	  assertDevelopmentAccessPolicy,
32	  type DevelopmentContracts,
33	  type DevelopmentAccessPolicy,
34	} from "./development-contracts.js";
35	import { readStoredResource } from "./resource-evaluator.js";
36	import { requestFromUrl, classifyAliasPath } from "./read-request.js";
37	
38	export const DEVELOPMENT_BEAD_TYPE = "https://bdp.example/development/bead";
39	export const DEVELOPMENT_LINK_TYPE = "https://bdp.example/development/link";
40	/** One immutable tuple consumed by owner, receiver and installed identity. */
41	export const DEVELOPMENT_OWNER_LIMITS = Object.freeze({
42	  update: Object.freeze({
43	    sequenceOperations: 32,
44	    requestBodyBytes: 64 * 1024,
45	    propertiesBytes: 64 * 1024,
46	    diagnosticBytes: 512 * 1024,
47	    diagnosticCount: 32,
48	  }),
49	  read: Object.freeze({
50	    page: Object.freeze({ defaultItems: 20, maximumItems: 100 }),
51	    selector: Object.freeze({ bytes: 4096, depth: 32, nodes: 256 }),
52	    cursorTtlMilliseconds: 60_000,
53	  }),
54	  member: Object.freeze({
55	    patchOperations: 128,
56	    patchPathBytes: 4096,
57	    patchPathDepth: 32,
58	    representationBytes: 256 * 1024,
59	  }),
60	  lifecycle: Object.freeze({
61	    retentionMs: 86_400_000,
62	    minimumRetentionMs: 86_400_000,
63	    maintenanceIntervalMs: 60_000,
64	  }),
65	  pagination: Object.freeze({
66	    retainedStateCapacity: 100,
67	    maxRetainedCursorPositionsPerSnapshot: 20,
68	    retainedSnapshotByteCapacity: 4 * 1024 * 1024,
69	    retainedSnapshotNodeCapacity: 100_000,
70	    maxOpaqueTokenLength: 64,
71	    tokenGenerationAttempts: 3,
72	    idleCleanup: "on-demand" as const,
73	  }),
74	  opaqueTokenBytes: 24,
75	});
76	export const DEVELOPMENT_LIMITS = DEVELOPMENT_OWNER_LIMITS.update;
77	export const DEVELOPMENT_READ_LIMITS = DEVELOPMENT_OWNER_LIMITS.read;
78	export const DEVELOPMENT_RETENTION_MS = DEVELOPMENT_OWNER_LIMITS.lifecycle.minimumRetentionMs;
79	const installation = "bdptest-development-2-revision-provenance";
80	const principal = Object.freeze({ id: "bdptest-development-operator" });
81	const policy = Object.freeze({
82	  canRead: () => true,
83	  canCreate: () => true,
84	  canWrite: () => true,
85	  canWriteBead: () => true,
86	});
87	const configuration = Object.freeze({
88	  policyIdentity: installation,
89	  configurationIdentity: installation,
90	  maximumEndpointMultiplicity: Object.freeze([]),
91	});
92	const descriptors = Object.freeze([
93	  parseTypeDescriptor({
94	    id: DEVELOPMENT_BEAD_TYPE,
95	    name: "Development Bead",
96	    describes: "bead",
97	    conformsTo: [],
98	  }),
99	  parseTypeDescriptor({
100	    id: DEVELOPMENT_LINK_TYPE,
101	    name: "Development Link",
102	    describes: "link",
103	    conformsTo: [],
104	    source: { conformsTo: [DEVELOPMENT_BEAD_TYPE], external: "opaque" },
105	    target: { conformsTo: [DEVELOPMENT_BEAD_TYPE], external: "opaque" },
106	  }),
107	]);
108	const types = Object.freeze(
109	  Object.fromEntries(descriptors.map((d) => [d.id, stringifyJsonValue(d)])),
110	);
111	
112	export interface DevelopmentAuthorityConfiguration {
113	  readonly contracts: DevelopmentContracts;
114	  readonly access: DevelopmentAccessPolicy;
115	  readonly maximumEndpointMultiplicity: readonly MaximumEndpointMultiplicityPolicy[];
116	}
117	export interface DevelopmentAuthorityOptions {
118	  readonly scope: string;
119	  readonly directory: string;
120	  /** Explicit first provisioning, never inferred from a missing database. */
121	  readonly create: boolean;
122	  /** Private composition seam; no scheduler enters public configuration. */
123	  readonly scheduler?: LifecycleScheduler;
124	  /** Private retention clock; absent in public development configuration. */
125	  readonly clock?: () => number;
126	  readonly configuration?: DevelopmentAuthorityConfiguration;
127	}
128	
129	export async function openDevelopmentAuthority(options: DevelopmentAuthorityOptions) {
130	  const scope = parseCanonicalScope(options.scope);
131	  const clock = options.clock ?? Date.now;
132	  const configured =
133	    options.configuration === undefined
134	      ? undefined
135	      : (Object.freeze(
136	          administrativeData(options.configuration, [
137	            "contracts",
138	            "access",
139	            "maximumEndpointMultiplicity",
140	          ]),
141	        ) as unknown as DevelopmentAuthorityConfiguration);
142	  if (configured) {
143	    assertDevelopmentContracts(configured.contracts);
144	    assertDevelopmentAccessPolicy(configured.access);
145	  }
146	  const installedDescriptors = configured?.contracts.descriptors ?? descriptors;
147	  const installedTypes = configured?.contracts.types ?? types;
148	  const contractIdentity = configured?.contracts.identity ?? installation;
149	  const aggregate = configured
150	    ? captureDevelopmentAggregatePolicy(
151	        configured.maximumEndpointMultiplicity,
152	        installedDescriptors,
153	      )
154	    : configuration.maximumEndpointMultiplicity;
155	  const installationIdentity = configured
156	    ? `${contractIdentity}-${createHash("sha256").update(stringifyJsonValue(aggregate)).digest("hex")}`
157	    : installation;
158	  // Scope-wide configuration digest; per-principal pagination authorization
159	  // uses the acting principal's separate snapshot identity below.
160	  const capturedConfiguration = () =>
161	    Object.freeze({
162	      policyIdentity: configured?.access.identity() ?? installation,
163	      configurationIdentity: installationIdentity,
164	      maximumEndpointMultiplicity: aggregate,
165	    });
166	  const capturedPolicy = (principal: StablePrincipal) => {
167	    if (!configured) return policy;
168	    const snapshot = configured.access.capture(principal.id);
169	    const local = (id: string) => (id.startsWith(scope) ? id.slice(scope.length) : id);
170	    const hidden = new Set(snapshot.hidden),
171	      readOnly = new Set(snapshot.readOnly);
172	    const canRead = (record: import("./resource-evaluator.js").ResourceRecord) =>
173	      !hidden.has(local(record.id));
174	    const canWrite = (record: import("./resource-evaluator.js").ResourceRecord) =>
175	      snapshot.write && !readOnly.has(local(record.id));
176	    return Object.freeze({
177	      canRead,
178	      canCreate: () => snapshot.create,
179	      canWrite,
180	      canWriteBead: canWrite,
181	    });
182	  };
183	  // Capture is immutable compiler evidence, not access/authentication policy.
184	  // Account for independent URI escaping and base64 artifact bytes plus entry overhead.
185	  // Twin ceiling: transaction-store.ts captureMaximumBytes. Keep these factors aligned;
186	  // consolidation is tracked in update-implementation-progress.md. This caller bounds
187	  // serialization; recovery-store.ts compares stored UTF8 length to this exact text.
188	  const contractCapture = configured ? stringifyJsonValue(configured.contracts.capture) : "null";
189	  const maximumCaptureBytes =
190	    8 * CONTRACT_ARTIFACT_CEILINGS.totalBytes +
191	    1024 * CONTRACT_ARTIFACT_CEILINGS.submittedArtifacts +
192	    4096;
193	  if (Buffer.byteLength(contractCapture) > maximumCaptureBytes)
194	    throw new TypeError("development installation capture exceeds private bound");
195	  const store = openRecoveryStore({
196	    contractCapture,
197	    expectedTypes: installedTypes,
198	    scope,
199	    directory: options.directory,
200	    installationId: installationIdentity,
201	    lineageId: installationIdentity,
202	    minimumRetentionMs: DEVELOPMENT_OWNER_LIMITS.lifecycle.minimumRetentionMs,
203	    ...(options.create ? { create: { types: installedTypes } } : {}),
204	  });
205	  let owner: SequenceLifecycle | undefined;
206	  try {
207	    // Capture and complete Type inventory were checked before claimed-key recovery.
208	    // Resource-Type and retained-runtime-limit checks below remain post-open checks.
209	    const installed = new Set(Object.keys(installedTypes));
210	    store.read((reader) => {
211	      for (const row of reader.resources()) {
212	        const resource = readStoredResource(row, scope);
213	        if (!installed.has(resource.type)) throw new Error("uninstalled development Resource Type");
214	      }
215	    });
216	    store.expire(clock());
217	    const bounds = snapshotReadUpdateRuntimeLimits(DEVELOPMENT_LIMITS);
218	    assertReadUpdateRuntimeCompatibility(store, bounds);
219	    owner = createSequenceLifecycle({
220	      store,
221	      ...(options.scheduler === undefined ? {} : { scheduler: options.scheduler }),
222	      maximumSequenceOperations: DEVELOPMENT_LIMITS.sequenceOperations,
223	      maintenanceIntervalMs: DEVELOPMENT_OWNER_LIMITS.lifecycle.maintenanceIntervalMs,
224	      member: {
225	        scope,
226	        limits: {
227	          ...bounds,
228	          ...DEVELOPMENT_OWNER_LIMITS.member,
229	        },
230	        numericBudget: {
231	          diagnostics: DEVELOPMENT_LIMITS.diagnosticCount,
232	          diagnosticBytes: bounds.diagnosticBytes,
233	          diagnostic: ({ pointer }) => ({
234	            message:
235	              pointer.startsWith("/propertiesChange/") || pointer.startsWith("/metadataChange/")
236	                ? `unsupported number at request location ${pointer}`
237	                : "unsupported number",
238	          }),
239	        },
240	        retentionMs: DEVELOPMENT_OWNER_LIMITS.lifecycle.retentionMs,
241	        minimumRetentionMs: DEVELOPMENT_OWNER_LIMITS.lifecycle.minimumRetentionMs,
242	        clock,
243	        contracts: configured?.contracts.registry ?? {
244	          get(id, bytes) {
245	            if (types[id] !== bytes) return undefined;
246	            const descriptor = descriptors.find((candidate) => candidate.id === id);
247	            return descriptor === undefined ? undefined : { descriptor };
248	          },
249	        },
250	        captureMemberContext(_reader, principal) {
251	          return {
252	            ...capturedConfiguration(),
253	            recordChangeContext: false,
254	            policy: capturedPolicy(principal),
255	          };
256	        },
257	      },
258	    });
259	    const epoch = randomBytes(DEVELOPMENT_OWNER_LIMITS.opaqueTokenBytes).toString("base64url");
260	    const readLimits = DEVELOPMENT_READ_LIMITS;
261	    const lifecycle = await createReadSequenceLifecycle({
262	      owner,
263	      read: {
264	        scopeEpoch: epoch,
265	        scopeConfiguration: { capture: capturedConfiguration },
266	        installedTypes: installedDescriptors,
267	        selectorLimits: readLimits.selector,
268	        advertisedLimits: readLimits,
269	        pagination: {
270	          scope,
271	          defaultPageItems: readLimits.page.defaultItems,
272	          maxPageItems: readLimits.page.maximumItems,
273	          cursorTtlMs: readLimits.cursorTtlMilliseconds,
274	          ...DEVELOPMENT_OWNER_LIMITS.pagination,
275	          clock: Date.now,
276	          generateOpaqueToken: () =>
277	            randomBytes(DEVELOPMENT_OWNER_LIMITS.opaqueTokenBytes).toString("base64url"),
278	        },
279	        captureReadAuthorization(_reader, readPrincipal) {
280	          if (readPrincipal.kind !== "authenticated")
281	            throw new TypeError("authenticated development Read required");
282	          const principal = readPrincipal.principal;
283	          return {
284	            kind: "authorized",
285	            authorization: {
286	              authorizationView: `${epoch}:${principal.id}:${configured?.access.capture(principal.id).identity ?? installation}`,
287	              scopeEpoch: epoch,
288	              policy: capturedPolicy(principal),
289	              canReadType: () => true,
290	            },
291	          };
292	        },
293	      },
294	    });
295	    const forPrincipal = (principal: StablePrincipal) => {
296	      const reads = lifecycle.readFor({ kind: "authenticated", principal });
297	      return Object.freeze({
298	        scope,
299	        // Private HTTP composition reads the very configuration used by this owner.
300	        limits: DEVELOPMENT_LIMITS,
301	        discover: () => reads.perform({ kind: "scope-discovery", scope }),
302	        resolveAlias: (url: string) => reads.resolveAlias(url),
303	        async perform(request: ReadRequest) {
304	          const result = await reads.perform(request);
305	          return result.kind === "success" ? { ...result, request } : result;
306	        },
307	        async mutate(
308	          operation: ReadUpdateOperation,
309	          text: string,
310	          key: string,
311	          acceptsJson = true,
312	        ) {
313	          const carrier = prepareReadUpdateSingleton(scope, operation, text, key);
314	          const submission = lifecycle.submit(carrier, principal, { acceptsJson });
315	          if (submission.kind === "refused") return submission.problem;
316	          if (submission.kind === "not-acceptable") return submission;
317	          const result = await submission.completion;
318	          if (result.kind !== "singleton") throw new Error("unexpected development completion");
319	          return result.disposition;
320	        },
321	        async sequence(text: string, acceptsJson = true) {
322	          const carrier = prepareReadUpdateSequence(scope, text);
323	          const submission = lifecycle.submit(carrier, principal, { acceptsJson });
324	          if (submission.kind === "refused") return submission.problem;
325	          if (submission.kind === "not-acceptable") return submission;
326	          const result = await submission.completion;
327	          if (result.kind !== "sequence") throw new Error("unexpected development completion");
328	          return result.response;
329	        },
330	        async read(url: URL) {
331	          if (classifyAliasPath(url, scope) !== undefined) return reads.resolveAlias(url.href);
332	          const request = requestFromUrl(url, scope);
333	          if (isReadProblem(request)) return { kind: "problem" as const, problem: request };
334	          const result = await reads.perform(request);
335	          return result.kind === "success" ? { ...result, request } : result;
336	        },
337	      });
338	    };
339	    return Object.freeze({
340	      ...(configured === undefined ? forPrincipal(principal) : {}),
341	      forPrincipal,
342	      /** Private bounded owner readback; epoch belongs to this lifecycle, not SQLite. */
343	      readConfiguration() {
344	        const rows: { readonly id: string; readonly bodyJson: string }[] = [];
345	        store.visitInstalledTypes((row) => rows.push(row));
346	        return Object.freeze({
347	          scope: store.scope,
348	          installedTypes: Object.freeze(rows),
349	          readLimits,
350	          scopeEpoch: epoch,
351	          scopeConfiguration: capturedConfiguration(),
352	        });
353	      },
354	      close: () => lifecycle.close(),
355	    });
356	  } catch (error) {
357	    if (owner) await owner.close();
358	    else store.close();
359	    throw error;
360	  }
361	}
