      types,
      ...(contracts ? { contracts } : {}),
      receiptMaximumItems: settings.receiptMaximumItems,
      maintenanceIntervalMs: settings.maintenanceIntervalMs,
      ...(capturedSeams.clock ? { clock: capturedSeams.clock } : {}),
