      checkPrepared();
      const actual = owner.readConfiguration();
      if (
        actual.receiptMaximumItems !== settings.receiptMaximumItems ||
        !isDeepStrictEqual(
          captured.readOptions(scope).advertisedLimits,
          prepared.handle.preflightReadLimits,
