1	/** Private administrative configuration for bounded development authorities.
2	 * Exact offline artifacts, existing guarded compiler, no public installation API.
3	 */
4	import { createHash } from "node:crypto";
5	import { isProxy } from "node:util/types";
6	import {
7	  stringifyJsonValue,
8	  assertCanonicalPathSegments,
9	  type MaximumEndpointMultiplicityPolicy,
10	  type PropertyValidator,
11	  type TypeDescriptor,
12	} from "@bdp/protocol";
13	import {
14	  ingestContractArtifacts,
15	  type ContractArtifactBundleInput,
16	  type ContractArtifactEntry,
17	  type ContractArtifactLimits,
18	} from "./installed-contract-artifact.js";
19	import { compilePrivateSchemaEvaluator, EVALUATOR_CEILINGS } from "./installed-schema-evaluator.js";
20	import { SCHEMA_GRAPH_CEILINGS } from "./installed-schema-shape.js";
21	import type { ResourceContractRegistry, InstalledResourceContract } from "./resource-evaluator.js";
22	
23	export function administrativeData(
24	  value: unknown,
25	  keys: readonly string[],
26	): Record<string, unknown> {
27	  if (
28	    !value ||
29	    typeof value !== "object" ||
30	    isProxy(value) ||
31	    ![Object.prototype, null].includes(Object.getPrototypeOf(value))
32	  )
33	    throw new TypeError("plain administrative data required");
34	  const descriptors = Object.getOwnPropertyDescriptors(value);
35	  if (
36	    Reflect.ownKeys(descriptors).length !== keys.length ||
37	    keys.some((k) => !descriptors[k] || !Object.hasOwn(descriptors[k], "value"))
38	  )
39	    throw new TypeError("exact administrative data fields required");
40	  return Object.fromEntries(keys.map((k) => [k, descriptors[k]?.value]));
41	}
42	export function administrativeArray(value: unknown, maximum: number): readonly unknown[] {
43	  if (!Array.isArray(value) || isProxy(value) || value.length > maximum)
44	    throw new TypeError("bounded administrative array required");
45	  const fields = Object.getOwnPropertyDescriptors(value);
46	  if (Reflect.ownKeys(fields).length !== value.length + 1)
47	    throw new TypeError("dense administrative array required");
48	  return Array.from({ length: value.length }, (_, i) => {
49	    const field = fields[String(i)];
50	    if (!field || !Object.hasOwn(field, "value"))
51	      throw new TypeError("administrative accessor refused");
52	    return field.value;
53	  });
54	}
55	
56	/** Exact immutable installation capture; policy constants are witnesses, not overrides. */
57	export interface DevelopmentContractCapture {
58	  readonly artifacts: readonly ContractArtifactEntry[];
59	  readonly artifactLimits: ContractArtifactLimits;
60	  readonly graphLimits: typeof SCHEMA_GRAPH_CEILINGS;
61	  readonly evaluatorLimits: typeof EVALUATOR_CEILINGS;
62	}
63	export interface DevelopmentContracts {
64	  readonly capture: DevelopmentContractCapture;
65	  readonly identity: string;
66	  readonly descriptors: readonly TypeDescriptor[];
67	  readonly types: Readonly<Record<string, string>>;
68	  readonly registry: ResourceContractRegistry;
69	}
70	const installed = new WeakSet<object>();
71	export function assertDevelopmentContracts(value: DevelopmentContracts): void {
72	  if (!installed.has(value)) throw new TypeError("compiled administrative contract required");
73	}
74	export function compileDevelopmentContracts(
75	  input: ContractArtifactBundleInput,
76	): DevelopmentContracts {
77	  const captured = ingestContractArtifacts(input);
78	  // Reconstruct solely from captured bytes: caller mutation/accessors cannot alter compilation.
79	  const artifact = (kind: "descriptor" | "schema") =>
80	    captured.artifacts
81	      .filter((a) => a.kind === kind)
82	      .map((a) => ({
83	        retrievalUri: a.retrievalUri,
84	        utf8Bytes: Buffer.from(a.bytesBase64, "base64"),
85	      }));
86	  const bundle = {
87	    descriptors: artifact("descriptor"),
88	    schemas: artifact("schema"),
89	    limits: captured.receipt.limits,
90	  };
91	  const types: Record<string, string> = Object.create(null);
92	  const contracts = new Map<string, InstalledResourceContract>();
93	  for (const descriptor of captured.descriptors) {
94	    if (Buffer.byteLength(JSON.stringify(descriptor.id)) > 4096)
95	      throw new RangeError("Type diagnostic identifier bound");
96	    types[descriptor.id] = stringifyJsonValue(descriptor);
97	    let validateProperties: PropertyValidator | undefined;
98	    if (descriptor.propertiesSchema !== undefined) {
99	      const compiled = compilePrivateSchemaEvaluator({
100	        bundle,
101	        entry: { kind: "descriptor", typeId: descriptor.id },
102	        graphLimits: SCHEMA_GRAPH_CEILINGS,
103	        limits: EVALUATOR_CEILINGS,
104	      });
105	      if (compiled.kind !== "compiled")
106	        throw new TypeError(`administrative schema refused: ${compiled.reason}`);
107	      validateProperties = (properties, emitter) => {
108	        const outcome = compiled.evaluateUtf8(Buffer.from(stringifyJsonValue(properties)));
109	        if (outcome.kind !== "evaluated")
110	          throw new Error("installed schema evaluation did not complete");
111	        if (outcome.valid) {
112	          if (!outcome.diagnosticsComplete)
113	            throw new Error("installed schema evaluation did not complete");
114	          return { valid: true };
115	        }
116	        if (!outcome.diagnostics.length) throw new Error("invalid schema result lacks diagnostics");
117	        for (const diagnostic of outcome.diagnostics) {
118	          if (
119	            Buffer.byteLength(JSON.stringify(diagnostic.schemaLocation)) > 16384 ||
120	            Buffer.byteLength(JSON.stringify(diagnostic.message)) > 1024
121	          )
122	            throw new Error("installed diagnostic metadata exceeds qualified bound");
123	          if (!emitter.emit(diagnostic)) return { valid: false, diagnosticsComplete: false };
124	        }
125	        // A confirmed prefix can satisfy a tighter receiver bound. Only claim
126	        // completeness when the evaluator actually reached its end.
127	        if (!outcome.diagnosticsComplete)
128	          throw new Error("installed schema evaluation did not complete");
129	        return { valid: false, diagnosticsComplete: true };
130	      };
131	    }
132	    contracts.set(
133	      descriptor.id,
134	      Object.freeze({ descriptor, ...(validateProperties ? { validateProperties } : {}) }),
135	    );
136	  }
137	  const value: DevelopmentContracts = Object.freeze({
138	    capture: Object.freeze({
139	      artifacts: captured.artifacts,
140	      artifactLimits: captured.receipt.limits,
141	      graphLimits: SCHEMA_GRAPH_CEILINGS,
142	      evaluatorLimits: EVALUATOR_CEILINGS,
143	    }),
144	    identity: `development-schema5-${createHash("sha256")
145	      .update(
146	        stringifyJsonValue({
147	          artifacts: captured.sha256,
148	          artifactLimits: captured.receipt.limits,
149	          graphLimits: SCHEMA_GRAPH_CEILINGS,
150	          evaluatorLimits: EVALUATOR_CEILINGS,
151	        }),
152	      )
153	      .digest("hex")}`,
154	    descriptors: captured.descriptors,
155	    types: Object.freeze(types),
156	    registry: Object.freeze({
157	      get: (id: string, bytes: string) => (types[id] === bytes ? contracts.get(id) : undefined),
158	    }),
159	  });
160	  installed.add(value);
161	  return value;
162	}
163	
164	export interface DevelopmentAccess {
165	  readonly create: boolean;
166	  readonly write: boolean;
167	  readonly hidden: readonly string[];
168	  readonly readOnly: readonly string[];
169	}
170	export interface DevelopmentAccessSnapshot extends DevelopmentAccess {
171	  readonly identity: string;
172	}
173	export interface DevelopmentAccessPolicy {
174	  identity(): string;
175	  capture(principal: string): DevelopmentAccessSnapshot;
176	}
177	const policies = new WeakSet<object>();
178	export function assertDevelopmentAccessPolicy(value: DevelopmentAccessPolicy): void {
179	  if (!policies.has(value)) throw new TypeError("administrative access policy required");
180	}
181	function access(value: DevelopmentAccess): DevelopmentAccessSnapshot {
182	  if (!value || typeof value !== "object" || isProxy(value))
183	    throw new TypeError("invalid access policy");
184	  const fields = Object.getOwnPropertyDescriptors(value);
185	  if (
186	    Reflect.ownKeys(fields).length !== 4 ||
187	    ["create", "write", "hidden", "readOnly"].some(
188	      (k) => !fields[k] || !Object.hasOwn(fields[k], "value"),
189	    )
190	  )
191	    throw new TypeError("invalid access policy fields");
192	  if (typeof fields.create?.value !== "boolean" || typeof fields.write?.value !== "boolean")
193	    throw new TypeError("invalid access flags");
194	  const ids = (v: unknown): readonly string[] => {
195	    const values = administrativeArray(v, 1000).map((id) => {
196	      if (typeof id !== "string" || (!id.startsWith("beads/") && !id.startsWith("links/")))
197	        throw new TypeError("invalid access resource identity");
198	      assertCanonicalPathSegments(id, "access resource identity");
199	      return id;
200	    });
201	    return Object.freeze([...new Set(values)].sort());
202	  };
203	  const snapshot = {
204	    create: fields.create.value as boolean,
205	    write: fields.write.value as boolean,
206	    hidden: ids(fields.hidden?.value),
207	    readOnly: ids(fields.readOnly?.value),
208	  };
209	  return Object.freeze({
210	    ...snapshot,
211	    identity: createHash("sha256").update(stringifyJsonValue(snapshot)).digest("hex"),
212	  });
213	}
214	/** Private operator handle replaces access atomically between synchronous owner turns.
215	 * Existing captures retain immutable values. No mutation request can reach replace.
216	 */
217	export function createDevelopmentAccessPolicy(
218	  initial: Readonly<Record<string, DevelopmentAccess>>,
219	) {
